const e=new class{constructor(){this.sizes=["small","medium","large"],this.currentSize=this.loadSize(),this.init()}init(){this.applySize(this.currentSize)}loadSize(){return localStorage.getItem("reader_fontSize")||"small"}saveSize(e){localStorage.setItem("reader_fontSize",e)}changeSize(e){this.sizes.includes(e)?(this.currentSize=e,this.saveSize(e),this.applySize(e)):console.error(`Invalid font size: ${e}`)}applySize(e){const t=document.body;this.sizes.forEach(e=>{t.classList.remove(`font-${e}`)}),t.classList.add(`font-${e}`),window.dispatchEvent(new CustomEvent("fontsizechange",{detail:{size:e}}))}increaseFontSize(){const e=this.sizes.indexOf(this.currentSize);if(e<this.sizes.length-1){const t=this.sizes[e+1];return this.changeSize(t),t}return this.currentSize}decreaseFontSize(){const e=this.sizes.indexOf(this.currentSize);if(e>0){const t=this.sizes[e-1];return this.changeSize(t),t}return this.currentSize}getSize(){return this.currentSize}isSmall(){return"small"===this.currentSize}isMedium(){return"medium"===this.currentSize}isLarge(){return"large"===this.currentSize}};document.addEventListener("keydown",t=>{!t.ctrlKey&&!t.metaKey||t.shiftKey||("="===t.key||"+"===t.key?(t.preventDefault(),e.increaseFontSize()):"-"===t.key?(t.preventDefault(),e.decreaseFontSize()):"0"===t.key&&(t.preventDefault(),e.changeSize("small")))});export{e as fontSizeManager};window.fontSizeManager=e;